PRAGMA foreign_keys = ON;
CREATE TABLE topics (id TEXT PRIMARY KEY, label TEXT NOT NULL, type TEXT NOT NULL CHECK(type IN ('Condition','Presentation')), systems TEXT NOT NULL DEFAULT '[]', blocks TEXT NOT NULL DEFAULT '[]', aliases TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE packs (id TEXT PRIMARY KEY, owner TEXT NOT NULL, title TEXT NOT NULL, mode TEXT NOT NULL, origin TEXT NOT NULL, created_at TEXT NOT NULL, request_hash TEXT NOT NULL);
CREATE TABLE questions (id TEXT PRIMARY KEY, pack_id TEXT NOT NULL REFERENCES packs(id), position INTEGER NOT NULL, payload TEXT NOT NULL, fingerprint TEXT NOT NULL, UNIQUE(pack_id,position));
CREATE INDEX question_pack ON questions(pack_id);
CREATE TABLE mappings (question_id TEXT PRIMARY KEY REFERENCES questions(id), topic_id TEXT NOT NULL REFERENCES topics(id), domain TEXT NOT NULL, confirmed_at TEXT NOT NULL);
CREATE TABLE mapping_proposals (id TEXT PRIMARY KEY, pack_id TEXT NOT NULL REFERENCES packs(id), owner TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL);
CREATE TABLE sessions (id TEXT PRIMARY KEY, owner TEXT NOT NULL, pack_id TEXT NOT NULL REFERENCES packs(id), revision INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'active', started_at TEXT NOT NULL, completed_at TEXT, state TEXT NOT NULL, score INTEGER NOT NULL DEFAULT 0, last_mutation TEXT);
CREATE INDEX session_owner ON sessions(owner,completed_at);
CREATE TABLE mutations (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), payload_hash TEXT NOT NULL, revision INTEGER NOT NULL);
CREATE TABLE answer_events (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), question_id TEXT NOT NULL REFERENCES questions(id), selection TEXT NOT NULL, sequence INTEGER NOT NULL, answered_at TEXT NOT NULL, received_at TEXT NOT NULL, UNIQUE(session_id,sequence));
CREATE INDEX answer_question ON answer_events(question_id);
CREATE TABLE exclusions (fingerprint TEXT PRIMARY KEY, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE reviews (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), owner TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE audit (id TEXT PRIMARY KEY, owner TEXT NOT NULL, action TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE sync_jobs (id TEXT PRIMARY KEY, owner TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_at TEXT NOT NULL, error TEXT, updated_at TEXT NOT NULL);
CREATE TABLE settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE web_sessions (token_hash TEXT PRIMARY KEY, owner TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE login_states (id TEXT PRIMARY KEY, nonce TEXT NOT NULL, return_to TEXT NOT NULL, expires_at INTEGER NOT NULL);
